// #662546 — /admin/tenders и /admin/tenders/<id> на 390 px (platform admin). Только чтение.
// Кейс: .qa/tests/admin-tenders/ADT-09. Вход platform один — отдельный serial-файл, --workers=1, не параллелить с другими platform-тестами.
// Таблица на 390 — отдельно в mobile-tables/admin-mobile.spec.ts (#3608cf); здесь — страница деталей и переход.
import { test, expect, Page, BrowserContext } from '@playwright/test';
import { authPath } from '../admin-companies-users/helpers';
import { OK_TENDER, openTenders, tendersRows, tendersSearch, detailsLink, expectDetailsPage } from './helpers';

test.describe.configure({ mode: 'serial' });
let ctx: BrowserContext;
let page: Page;

test.beforeAll(async ({ browser }, testInfo) => {
  const u = testInfo.project.use as Record<string, any>;
  ctx = await browser.newContext({ baseURL: u.baseURL, locale: u.locale, viewport: { width: 390, height: 844 }, storageState: authPath('platform') });
  page = await ctx.newPage();
});
test.afterAll(async () => {
  await ctx?.close();
});

test('במובייל 390px: מעבר מ«פרטי מכרז» לדף הפרטים, בלי גלישה אופקית של הדף #662546 @mobile @prod-safe', async () => {
  // ADT-09
  await openTenders(page);
  await tendersSearch(page).fill(OK_TENDER.title);
  const row = tendersRows(page).filter({ hasText: OK_TENDER.title });
  await expect(row).toHaveCount(1);
  await detailsLink(row).scrollIntoViewIfNeeded();
  await detailsLink(row).click();
  await expectDetailsPage(page, OK_TENDER.id);
  await expect
    .poll(() => page.evaluate(() => ({ iw: window.innerWidth, sw: document.documentElement.scrollWidth, sx: window.scrollX })))
    .toEqual({ iw: 390, sw: 390, sx: 0 });
  await expect(page.getByRole('link', { name: 'חזרה למכרזים שנקלטו' })).toBeInViewport();
});
